{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect Specification Document and Feature Change List",
        "actor": "Document Reviewer",
        "system": "Document Repository",
        "inputs": ["Specification Document", "Feature Change List"],
        "outputs": ["Collected Review Package"]
      },
      {
        "id": "A2",
        "name": "Review Feature Coverage Against Change List",
        "actor": "Document Reviewer",
        "system": "Document Repository, Commenting Tool",
        "inputs": ["Collected Review Package", "Review Checklist"],
        "outputs": ["Feature Coverage Assessment", "Review Comments (if issues found)"]
      },
      {
        "id": "A3",
        "name": "Review Terminology and Formatting Consistency",
        "actor": "Document Reviewer",
        "system": "Document Repository, Commenting Tool",
        "inputs": ["Collected Review Package", "Review Checklist"],
        "outputs": ["Terminology and Formatting Assessment", "Review Comments (if issues found)"]
      },
      {
        "id": "A4",
        "name": "Record Review Comments",
        "actor": "Document Reviewer",
        "system": "Commenting Tool",
        "inputs": ["Feature Coverage Assessment", "Terminology and Formatting Assessment"],
        "outputs": ["Consolidated Review Comments"]
      },
      {
        "id": "A5",
        "name": "Revise Specification Document Based on Comments",
        "actor": "Document Author",
        "system": "Document Repository, Commenting Tool",
        "inputs": ["Consolidated Review Comments", "Original Specification Document"],
        "outputs": ["Revised Specification Document"]
      },
      {
        "id": "A6",
        "name": "Confirm Revisions",
        "actor": "Feature Owner",
        "system": "Document Repository, Commenting Tool",
        "inputs": ["Revised Specification Document", "Feature Change List"],
        "outputs": ["Revision Confirmation"]
      },
      {
        "id": "A7",
        "name": "Make Final Approval Decision",
        "actor": "Approver",
        "system": "Document Repository",
        "inputs": ["Revised Specification Document", "Revision Confirmation"],
        "outputs": ["Approval Decision"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are all feature changes reflected correctly in the specification document?",
        "branches": [
          {
            "outcome": "Yes — all changes reflected",
            "next": "A7",
            "description": "Document proceeds toward approval"
          },
          {
            "outcome": "No — changes are missing or incorrect",
            "next": "A4",
            "description": "Reviewer records comments; document author must revise"
          }
        ]
      },
      {
        "id": "D2",
        "condition": "Does the approver approve the document or request another revision?",
        "branches": [
          {
            "outcome": "Approved",
            "next": "END",
            "description": "Document is formally approved and process ends"
          },
          {
            "outcome": "Another revision requested",
            "next": "A5",
            "description": "Document author revises again based on approver feedback"
          }
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "Feature owner cannot confirm revisions due to ambiguity in the feature change list",
        "handling": "Escalate to document reviewer or relevant stakeholder for clarification before proceeding to approval"
      },
      {
        "id": "E2",
        "description": "Specification document is unavailable or inaccessible in the document repository",
        "handling": "Notify document author or repository administrator; review cannot begin until document is accessible"
      }
    ],
    "dependencies": [
      {
        "from": "A1",
        "to": "A2",
